package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import tools.jackson.databind.node.ObjectNode;

/**
 * cp16: namesakeCount — when an owner is created it records how many other owners
 * already share its last name at that moment.
 */
@Tag("cp16")
class Cp16Tests extends AcceptanceBase {

	@Test
	void firstOfASurnameHasNoNamesakes() throws Exception {
		int id = createOwnerOk(ownerNode());
		getOwner(id).andExpect(jsonPath("$.namesakeCount").value(0));
	}

	@Test
	void countsExistingOwnersWithTheSameLastName() throws Exception {
		String surname = uniqueLastName();

		int first = createOwnerOk(withLastName(surname));
		getOwner(first).andExpect(jsonPath("$.namesakeCount").value(0));

		int second = createOwnerOk(withLastName(surname));
		getOwner(second).andExpect(jsonPath("$.namesakeCount").value(1));

		int third = createOwnerOk(withLastName(surname));
		getOwner(third).andExpect(jsonPath("$.namesakeCount").value(2));
	}

	@Test
	void namesakesAreCountedPerLastNameNotGlobally() throws Exception {
		createOwnerOk(withLastName(uniqueLastName()));

		int other = createOwnerOk(withLastName(uniqueLastName()));
		getOwner(other).andExpect(jsonPath("$.namesakeCount").value(0));
	}

	/** A fully unique owner overridden to use the given last name. */
	private ObjectNode withLastName(String lastName) {
		ObjectNode owner = ownerNode();
		owner.put("lastName", lastName);
		return owner;
	}
}

